const paths={society:'<circle cx="12" cy="4" r="2"/><circle cx="5" cy="20" r="2"/><circle cx="19" cy="20" r="2"/><path d="M12 6v7M5 18v-5h14v5"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="4" rx="1"/><rect x="14" y="11" width="7" height="10" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',wallet:'<path d="M20 8V5a2 2 0 0 0-2-2H5a3 3 0 0 0 0 6h15v12H5a3 3 0 0 1-3-3V6m18 6h-5v5h5"/><path d="M17 14.5h.1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h.01m4 0h.01m4 0h.01"/>',calc:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 6h8m-8 5h1m3 0h1m3 0h.01M8 15h1m3 0h1m3 0h.01M8 19h1m3 0h1m3 0h.01"/>',receipt:'<path d="M4 3l2 1 2-1 2 1 2-1 2 1 2-1 2 1 2-1v19l-2-1-2 1-2-1-2 1-2-1-2 1-2-1-2 1zM8 8h8m-8 4h8m-8 4h5"/>',settings:'<path d="M12 3l2 3 3-.5.5 3 3 2-1.5 3 1 3-3 1-1 3-3-1-3 1-2-3-3-.5.5-3-2-2 2-3-.5-3 3-.5z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M7 17L17 7M7 7h10v10"/>',down:'<path d="M7 7l10 10M7 17h10V7"/>',chevron:'<path d="M9 5l7 7-7 7"/>',search:'<circle cx="10.5" cy="10.5" r="7"/><path d="M16 16l5 5"/>',shield:'<path d="M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',logout:'<path d="M9 4H4v16h5m6-14 6 6-6 6m-6-6h12"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',print:'<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z"/>',whatsapp:'<path d="M21 11.5a9 9 0 0 1-13 8L3 21l1.5-5A9 9 0 1 1 21 11.5Z"/><path d="M8 7c1 5 4 8 9 9l1-3-3-1-1 1-3-3 1-1-1-3z"/>',check:'<path d="M5 12l4 4L19 6"/>',close:'<path d="M6 6l12 12M6 18L18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',refresh:'<path d="M20 7V3l-4 1M4 17v4l4-1M20 7a9 9 0 0 0-16 2m0 8a9 9 0 0 0 16-2"/>',edit:'<path d="M16 3l5 5L8 21H3v-5zM13 6l5 5"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 6l9 7 9-7"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.wallet}</svg>`;
const btn=(label,action,ic='',cls='',data='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${data}>${ic?icon(ic):''}${label}</button>`;
const link=(label,href,ic='',cls='')=>`<a class="btn ${cls}" href="${h(href)}">${ic?icon(ic):''}${label}</a>`;
const statusLabels={paid:'Pago',overdue:'Em atraso',today:'Vence hoje',pending:'A vencer',partial:'Parcial',cancelled:'Cancelado'};
const badge=s=>`<span class="badge ${s}">${statusLabels[s]||h(s)}</span>`;
const initials=name=>h((name||'JK').split(' ').filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase());
const nameCell=c=>`<div class="name-cell"><span class="avatar">${initials(c?.name)}</span><div><strong>${h(c?.name||'Cliente')}</strong><small>${h(c?.phone?phoneFormat(c.phone):'')}</small></div></div>`;
const empty=(title,desc,action='')=>`<div class="empty">${icon('wallet')}<strong>${title}</strong><p>${desc}</p>${action}</div>`;
const el=document.getElementById('app'),modal=document.getElementById('modal');
let session,model={clients:[],loans:[],items:[],receipts:[]},events=[],preferences={default_rate_bps:3000,default_fee_cents:1000,due_window:7,message_template:''},route='',filter='',search='',periodFrom='',periodTo='',builder=null,currentMessage='',selectedLoan=null,saveBusy=false,loadEpoch=0;
let cashRecords={account:{balance_cents:0},entries:[]},cashSyncBusy=false;
const cash=createCashPanel({getData:()=>({...cashRecords,model,partners:societyRecords.partners}),api:rpc,reload:load,repaint:render,showModal,toast,friendly,setBusy:value=>{saveBusy=value;updateCashPreview();},isBusy:()=>saveBusy,isActive:()=>route==='cash',head,icon,btn});
const cep=createCepAutofill({lookup:(value,signal)=>rpc('lookup_cep',{cep:value},{signal}),onAddressChange:group=>{if(group.closest('#adhesion-form')&&builder?.mode==='new'){builder.client=Object.fromEntries(new FormData(group.closest('form')));updatePreview(false);}}});
let societyRecords={partners:[],settings:{version:1},splits:[],payouts:[]},societySyncBusy=false;
const society=createSocietyPanel({getData:()=>({...societyRecords,model,refreshedAt:lastLoadedAt}),getCashBalance:()=>Number(cashRecords.account.balance_cents),api:rpc,reload:load,repaint:render,showModal,toast,friendly,setBusy:value=>{saveBusy=value;},isBusy:()=>saveBusy,isActive:()=>route==='society',head,icon,btn});
let calendarMonth=today().slice(0,7),calendarSelected=today(),lastLoadedAt=0,calendarSyncBusy=false;
const titles={cash:'Fundo de caixa',society:'Repasse societário',calendar:'Calendário',dashboard:'Visão geral',clients:'Clientes',loans:'Empréstimos',schedule:'Vencimentos',simulation:'Calculadora',adhesion:'Nova adesão',receipts:'Recebimentos',settings:'Configurações',client:'Cadastro de cliente'};
function toast(text,error=false){const node=document.getElementById('toast');node.textContent=text;node.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.className='',4500);}
function friendly(error){const msg=error?.message||String(error);if(/duplicate key|unique constraint/i.test(msg))return 'Já existe um cadastro com este CPF, ou esta operação já foi registrada. Atualize a lista.';if(/Failed to fetch|NetworkError/i.test(msg))return 'Não foi possível conectar. Confira a internet e tente novamente.';if(/check constraint/i.test(msg))return 'Confira os dados: CPF, telefone, datas e valores devem ser válidos.';return msg;}
async function rpc(name,args={},options={}){const response=await fetch('/api/gateway',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:name,args}),signal:options.signal});let result;try{result=await response.json();}catch{throw new Error('Sua sessão privada expirou. Atualize a página para continuar.');}if(!response.ok||result.error)throw new Error(result.error||'Não foi possível concluir a operação.');return result.data;}
async function fetchAll(table){let records=[];for(let from=0;;from+=500){const data=await rpc('load_table',{table,from});records.push(...data);if(data.length<500)break;}return records;}
async function load(){const epoch=++loadEpoch;const [clients,loans,items,receipts,prefs,eventRows,partners,societySettings,splits,payouts,cashSnapshot]=await Promise.all([...['jk_clients','jk_loans','jk_installments','jk_receipts','jk_preferences','jk_events','jk_society_partners','jk_society_settings','jk_society_splits','jk_society_payouts'].map(fetchAll),rpc('jk_cash_snapshot')]);if(epoch!==loadEpoch||!session)return;model=enrich(clients,loans,items,receipts);preferences=prefs[0]||preferences;events=eventRows.sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,30);societyRecords={partners,settings:societySettings[0]||{version:1},splits,payouts};cashRecords=cashSnapshot;lastLoadedAt=Date.now();refreshCalendar();society.refresh();cash.refresh();updateCashPreview();}
async function syncSociety(){if(!session||route!=='society'||saveBusy||societySyncBusy||document.visibilityState==='hidden')return;societySyncBusy=true;try{await load();}catch{const node=document.querySelector('.society-sync');if(node)node.textContent='Não foi possível atualizar agora. Tentaremos novamente automaticamente.';}finally{societySyncBusy=false;}}
async function syncCash(){if(!session||!['cash','dashboard'].includes(route)||saveBusy||cashSyncBusy||document.visibilityState==='hidden')return;cashSyncBusy=true;try{await load();}catch{const node=document.querySelector('.cash-sync');if(node)node.textContent='Não foi possível atualizar o caixa agora. Tentaremos novamente automaticamente.';}finally{cashSyncBusy=false;}}
function navigate(path){if(location.hash==='#/'+path)render();else location.hash='/'+path;}
function head(title,subtitle,actions='',eyebrow='JK CRED / GESTÃO FINANCEIRA'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function shell(content){const nav=[['dashboard','dashboard','Visão geral'],['clients','users','Clientes'],['loans','wallet','Empréstimos'],['calendar','calendar','Calendário'],['schedule','clock','Vencimentos'],['receipts','receipt','Recebimentos'],['cash','wallet','Fundo de caixa'],['simulation','calc','Calculadora']];const overdue=model.items.filter(i=>i.status==='overdue').length;return `<div class="shell"><aside class="sidebar"><a class="brand" href="#/dashboard"><img src="assets/logo.svg" alt="JK CRED"><span class="brand-caption">GESTÃO<br>FINANCEIRA</span></a><div class="nav-label">PRINCIPAL</div><nav class="nav" aria-label="Menu principal">${nav.map(([key,ic,label])=>`<a href="#/${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(ic)}${label}${key==='schedule'&&overdue?`<span class="nav-count">${overdue}</span>`:''}</a>`).join('')}</nav><div class="nav-label">ADMINISTRAÇÃO</div><nav class="nav"><a href="#/adhesion" class="${route==='adhesion'?'active':''}">${icon('plus')}Nova adesão</a><a href="#/society" class="${route==='society'?'active':''}" ${route==='society'?'aria-current="page"':''}>${icon('society')}Repasse societário</a><a href="#/settings" class="${route==='settings'?'active':''}">${icon('settings')}Configurações</a></nav><div class="sidebar-bottom"><div class="security">${icon('shield')}<div>Ambiente administrativo<br><strong>Dados protegidos</strong></div></div><div class="user"><span class="avatar">${initials('JK')}</span><div class="user-meta"><strong>Administrador</strong><span>${h('Acesso privado')}</span></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${btn('<span class="visually-hidden">Abrir menu</span>','menu','menu','icon-only ghost mobile-menu')}<span>Painel administrativo</span><span>/</span><strong>${titles[route]||'Visão geral'}</strong></div><div class="top-meta"><span class="date-display">${dateLabel(today())}</span><span><i class="dot"></i>Conectado</span>${btn('<span class="visually-hidden">Atualizar dados</span>','refresh','refresh','icon-only ghost')}</div></header><main class="content" id="main">${content}</main></div></div>`;}
const activeLoans=()=>model.loans.filter(l=>l.status==='active');
const openItems=()=>model.items.filter(i=>i.loan?.status==='active'&&i.balance>0);
const sum=(array,key)=>array.reduce((s,x)=>s+Number(typeof key==='function'?key(x):x[key]||0),0);
function stat(label,value,caption,ic,cls=''){return `<div class="stat ${cls}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-bottom">${caption}</div></div>`;}
function dashboard(){const loans=activeLoans(),items=openItems(),overdue=items.filter(i=>i.status==='overdue'),upcoming=items.filter(i=>i.due_on>=today()&&i.due_on<=dateAdd(today(),preferences.due_window)),received=model.receipts.filter(r=>!r.voided_at),principal=sum(loans,'principal_cents'),paid=sum(received,'amount_cents'),balance=sum(items,'balance');const next=items.filter(i=>i.due_on>=today()).sort((a,b)=>a.due_on.localeCompare(b.due_on)).slice(0,5);const ranking=model.clients.map(c=>({...c,balance:sum(loans.filter(l=>l.client_id===c.id),'balance')})).filter(c=>c.balance>0).sort((a,b)=>b.balance-a.balance).slice(0,4);const months=Array.from({length:6},(_,i)=>{const d=new Date(today()+'T12:00:00Z');d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()-5+i);const key=d.toISOString().slice(0,7);return {label:d.toLocaleDateString('pt-BR',{month:'short',timeZone:'UTC'}).replace('.',''),loan:sum(loans.filter(l=>l.released_on.startsWith(key)),'principal_cents'),paid:sum(received.filter(r=>r.paid_on.startsWith(key)),'amount_cents')};});const max=months.reduce((v,m)=>Math.max(v,m.loan,m.paid),1);const recent=loans.slice().sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,5);const currentMonth=today().slice(0,7);return head('Seu negócio, em perspectiva.','Acompanhe sua carteira e cuide de cada detalhe.',link('Nova adesão','#/adhesion','plus','primary'))+`${cash.dashboardHero()}<div class="hero-strip"><div><h2>${icon('calendar')} &nbsp; Sua agenda financeira</h2><p>${upcoming.length?`${upcoming.length} parcela(s) vencem nos próximos ${preferences.due_window} dias • ${money(sum(upcoming,'balance'))} a receber.`:'Tudo em dia. Os próximos vencimentos aparecerão aqui.'}${overdue.length?` Há ${overdue.length} parcela(s) em atraso.`:''}</p></div>${link('Ver vencimentos','#/schedule','chevron','ghost')}</div><div class="stats">${stat('Total emprestado',money(principal),`${loans.length} contrato(s) não cancelado(s)`,'wallet','highlight')}${stat('Saldo a receber',money(balance),'Juros e acréscimos incluídos','arrow')}${stat('Total recebido',money(paid),'Pagamentos confirmados, sem estornos','receipt')}${stat('Em atraso',money(sum(overdue,'balance')),`${overdue.length} parcela(s) vencida(s)`,'clock','red')}</div>${cash.dashboardCharts()}<div class="grid-dashboard"><section class="card"><div class="card-head"><div><h2>Movimentação da carteira</h2><p>Valores liberados e recebidos nos últimos 6 meses</p></div><div class="legend"><span>Emprestado</span><span>Recebido</span></div></div><div class="card-body"><div class="chart" role="img" aria-label="Gráfico de empréstimos e recebimentos por mês">${months.map(m=>`<div class="chart-col" title="${h(m.label)}: emprestado ${money(m.loan)}, recebido ${money(m.paid)}"><div class="chart-bar" style="height:${Math.round(m.loan/max*95)}%"></div><div class="chart-bar received" style="height:${Math.round(m.paid/max*95)}%"></div><span class="chart-label">${h(m.label)}</span></div>`).join('')}</div><div class="chart-footer"><div>Liberado neste mês<strong>${money(sum(loans.filter(l=>l.released_on.startsWith(currentMonth)),'principal_cents'))}</strong></div><div>Recebido neste mês<strong>${money(sum(received.filter(r=>r.paid_on.startsWith(currentMonth)),'amount_cents'))}</strong></div><div>Encargos contratados<strong>${money(sum(loans,l=>l.total_cents-l.principal_cents))}</strong></div></div></div></section><section class="card"><div class="card-head"><div><h2>Próximos vencimentos</h2><p>Sua atenção, no momento certo</p></div>${link('Ver todos','#/schedule','','sm ghost')}</div><div class="card-body">${next.length?next.map(i=>`<div class="list-row"><span class="avatar">${initials(i.client?.name)}</span><div class="grow"><strong>${h(i.client?.name)}</strong><small>${dateLabel(i.due_on)} • Parcela ${i.number}/${i.loan.count}</small></div><div class="amount">${money(i.balance)}<div style="margin-top:7px">${badge(i.status)}</div></div></div>`).join(''):empty('Nenhum vencimento próximo','Cadastre uma adesão para acompanhar as parcelas.')}</div></section></div><div class="grid-dashboard"><section class="card"><div class="card-head"><div><h2>Últimos empréstimos</h2><p>Contratos recentes da sua carteira</p></div>${link('Ver todos','#/loans','','sm ghost')}</div>${recent.length?loanTable(recent):empty('Sua carteira começa aqui','Registre seu primeiro empréstimo e acompanhe tudo em um só lugar.',link('Criar adesão','#/adhesion','plus','primary'))}</section><section class="card"><div class="card-head"><div><h2>Saldo por cliente</h2><p>Os maiores saldos em aberto</p></div>${icon('users')}</div><div class="card-body">${ranking.length?ranking.map(c=>`<div class="list-row"><div class="grow"><strong>${h(c.name)}</strong><div class="progress"><span style="width:${Math.round(c.balance/ranking[0].balance*100)}%"></span></div></div><span class="amount">${money(c.balance)}</span>${btn('<span class="visually-hidden">Ver cliente</span>','client-detail','chevron','sm ghost',`data-id="${c.id}"`)}</div>`).join(''):empty('Nenhum saldo em aberto','Os saldos dos seus clientes serão exibidos aqui.')}</div></section></div><div class="summary-mini">${[['Clientes cadastrados',model.clients.filter(c=>!c.archived).length],['Contratos com saldo',loans.filter(l=>l.balance>0).length],['Recebimento da carteira',principal?`${Math.round(paid/sum(loans,'total_cents')*100)}%`:'0%']].map(([l,v])=>`<div class="mini"><small>${l}</small><strong>${v}</strong></div>`).join('')}</div>`;}
function loanTable(loans){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente / contrato</th><th>Liberado</th><th>Total / saldo</th><th>Parcelas</th><th>Situação</th><th></th></tr></thead><tbody>${loans.map(l=>`<tr><td>${nameCell(l.client)}<div class="muted small" style="margin-top:7px;font-size:9px">${h(l.protocol)}</div></td><td>${money(l.principal_cents)}<div class="muted small">${l.rate_bps/100}% de juros</div></td><td>${money(l.total_cents)}<div class="muted small">Saldo: ${money(l.status==='cancelled'?0:l.balance)}</div></td><td>${l.installments.filter(i=>i.balance===0).length}/${l.count} pagas</td><td>${badge(l.status==='cancelled'?'cancelled':l.balance===0?'paid':l.installments.some(i=>i.status==='overdue')?'overdue':'pending')}</td><td>${btn('Detalhes','loan-detail','chevron','sm ghost',`data-id="${l.id}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
function toolbar(placeholder,filters=[],exportAction=''){return `<div class="toolbar"><div class="search">${icon('search')}<input id="search" aria-label="Pesquisar" placeholder="${placeholder}" value="${h(search)}"></div><div class="filters">${filters.map(([key,label])=>`<button class="filter ${filter===key?'active':''}" type="button" data-action="filter" data-filter="${key}">${label}</button>`).join('')}${exportAction?btn('Exportar CSV',exportAction,'download','ghost'):''}</div></div>`;}
function clientsPage(){return head('Pessoas por trás dos números.','Cadastros completos e histórico financeiro em um só lugar.',link('Adicionar cliente','#/client','plus','primary'))+toolbar('Nome, CPF, telefone ou e-mail',[['','Ativos'],['archived','Arquivados']],'export-clients')+`<section class="card" id="results">${clientsResults()}</section>`;}
function clientsResults(){const q=search.toLowerCase(),clients=model.clients.filter(c=>(filter==='archived'?c.archived:!c.archived)&&[c.name,c.cpf,cpfFormat(c.cpf),c.phone,c.email].join(' ').toLowerCase().includes(q));return clients.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>CPF</th><th>Localização</th><th>Contratos</th><th>Saldo devedor</th><th></th></tr></thead><tbody>${clients.map(c=>{const loans=activeLoans().filter(l=>l.client_id===c.id);return `<tr><td>${nameCell(c)}<div class="muted small" style="margin-top:5px;font-size:10px">${h(c.email)}</div></td><td>${cpfFormat(c.cpf)}</td><td>${h(c.city||'—')}${c.state?' / '+h(c.state):''}</td><td>${loans.length}</td><td>${money(sum(loans,'balance'))}</td><td><div class="actions">${btn('Ver ficha','client-detail','chevron','sm ghost',`data-id="${c.id}"`)}${link('<span class="visually-hidden">Editar cliente</span>','#/client/'+c.id,'edit','sm ghost')}</div></td></tr>`;}).join('')}</tbody></table></div><div class="count-text">${clients.length} cliente(s)</div>`:empty('Nenhum cliente encontrado','Cadastre um cliente ou ajuste sua pesquisa.');}
function loansPage(){return head('Sua carteira de empréstimos.','Detalhes dos contratos, pagamentos e saldos atualizados.',link('Novo empréstimo','#/adhesion','plus','primary'))+toolbar('Cliente ou número do contrato',[['','Todos'],['active','Em aberto'],['paid','Quitados'],['overdue','Em atraso'],['cancelled','Cancelados']],'export-loans')+`<section class="card" id="results">${loansResults()}</section>`;}
function loansResults(){const q=search.toLowerCase(),loans=model.loans.filter(l=>[l.client?.name,l.protocol].join(' ').toLowerCase().includes(q)&&(!filter||filter==='cancelled'&&l.status==='cancelled'||filter==='active'&&l.status==='active'&&l.balance>0||filter==='paid'&&l.status==='active'&&l.balance===0||filter==='overdue'&&l.status==='active'&&l.installments.some(i=>i.status==='overdue'))).sort((a,b)=>b.created_at.localeCompare(a.created_at));return loans.length?loanTable(loans)+`<div class="count-text">${loans.length} contrato(s)</div>`:empty('Nenhum contrato encontrado','Registre um empréstimo ou ajuste os filtros.');}
const calendarPerson=()=>`<svg class="calendar-person" viewBox="0 0 24 26" aria-hidden="true"><circle cx="12" cy="6.5" r="4.5" fill="#f1d38b"/><path d="M3.5 24v-3.5a8.5 8.5 0 0 1 17 0V24Z" fill="#cfa342"/><path d="M5.5 21a6.5 6.5 0 0 1 10.8-4.9" fill="none" stroke="#f6dfa2" stroke-width="1.5" stroke-linecap="round"/></svg>`;
const calendarLabel=date=>new Intl.DateTimeFormat('pt-BR',{day:'numeric',month:'long',year:'numeric',weekday:'long',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));
function calendarPage(){return head('Sua agenda de recebimentos.','Um olhar no mês para saber quem paga, quando e quanto.',link('Nova adesão','#/adhesion','plus','primary'))+`<div id="calendar-view">${calendarContent()}</div>`;}
function calendarContent(){
 const current=today(),agenda=dueCalendar(model.items,calendarMonth),selected=agenda.groups.get(calendarSelected),items=selected?.items||[];
 const monthTitle=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(calendarMonth+'-01T12:00:00Z')).replace(/^./,letter=>letter.toUpperCase());
 const dates=monthDays(calendarMonth),nextDate=[...agenda.groups.keys()].filter(date=>date>calendarSelected).sort()[0];
 const summary=[['A receber no mês',money(agenda.balance),`${agenda.items.length} parcela(s) em aberto`],['Clientes no mês',agenda.clients,'Com parcelas a receber'],['Dias com vencimentos',agenda.days,'Marcados com a pessoa dourada']];
 return `<div class="calendar-summary">${summary.map(([label,value,caption])=>`<div class="calendar-stat"><span>${label}</span><strong>${value}</strong><small>${caption}</small></div>`).join('')}</div>
 <div class="calendar-layout"><section class="card calendar-card" aria-labelledby="calendar-month-title">
 <div class="calendar-heading"><div><div class="eyebrow">AGENDA MENSAL</div><h2 id="calendar-month-title">${h(monthTitle)}</h2></div><div class="calendar-controls">${btn('<span class="visually-hidden">Mês anterior</span>','calendar-prev','chevron','icon-only ghost calendar-prev','data-calendar-focus="prev"')}${btn('Hoje','calendar-today','','ghost','data-calendar-focus="today"')}${btn('<span class="visually-hidden">Próximo mês</span>','calendar-next','chevron','icon-only ghost','data-calendar-focus="next"')}</div></div>
 <table class="calendar-table" aria-labelledby="calendar-month-title"><thead><tr>${[['DOM','Domingo'],['SEG','Segunda-feira'],['TER','Terça-feira'],['QUA','Quarta-feira'],['QUI','Quinta-feira'],['SEX','Sexta-feira'],['SÁB','Sábado']].map(([short,full])=>`<th scope="col"><abbr title="${full}">${short}</abbr></th>`).join('')}</tr></thead><tbody>${Array.from({length:6},(_,week)=>`<tr>${dates.slice(week*7,week*7+7).map(date=>{
  const due=agenda.groups.get(date),outside=!date.startsWith(calendarMonth),isToday=date===current,isSelected=date===calendarSelected,overdue=due&&date<current;
  const description=`${calendarLabel(date)}. ${due?`${due.clients.size} cliente(s), ${due.items.length} parcela(s), ${money(due.balance)} a receber${overdue?', em atraso':''}`:'Nenhuma parcela em aberto'}`;
  return `<td><button type="button" class="calendar-day${outside?' outside':''}${due?' has-dues':''}${isToday?' is-today':''}${isSelected?' is-selected':''}${overdue?' is-overdue':''}" data-action="calendar-day" data-date="${date}" data-calendar-focus="${date}" aria-label="${h(description)}" aria-pressed="${isSelected}" ${isToday?'aria-current="date"':''} title="${h(description)}"><span class="calendar-day-number">${Number(date.slice(-2))}</span>${due?`<span class="calendar-marker">${calendarPerson()}<span class="calendar-marker-count">${due.clients.size}</span></span><span class="calendar-cell-amount">${money(due.balance)}</span>`:'<span class="calendar-day-space" aria-hidden="true"></span>'}</button></td>`;
 }).join('')}</tr>`).join('')}</tbody></table>
 <div class="calendar-legend"><span>${calendarPerson()}Cliente com parcela a receber</span><span><i class="calendar-today-ring"></i>Hoje</span><span><i class="calendar-late-dot"></i>Em atraso</span></div></section>
 <section class="card calendar-detail" aria-labelledby="calendar-day-title"><div class="calendar-detail-heading"><div class="eyebrow">AGENDA DO DIA</div><h2 id="calendar-day-title">${dateLabel(calendarSelected)}</h2><p>${h(calendarLabel(calendarSelected))}</p></div>
 <div class="calendar-day-total"><span>Saldo a receber<strong>${money(selected?.balance||0)}</strong></span><small>${selected?.clients.size||0} cliente(s)<br>${items.length} parcela(s)</small></div>
 <div class="calendar-day-list">${items.length?items.map(item=>`<article class="calendar-entry">${nameCell(item.client)}<div class="calendar-entry-meta"><span>Parcela ${item.number}/${item.loan.count}</span>${badge(item.status)}</div><span class="calendar-contract">${h(item.loan.protocol)}</span><div class="calendar-entry-value"><span>Falta receber</span><strong>${money(item.balance)}</strong></div>${item.paid?`<p class="calendar-partial">Já recebido: ${money(item.paid)} de ${money(item.amount_cents)}</p>`:''}<div class="actions">${btn('Receber','payment','plus','sm primary',`data-id="${h(item.id)}" data-calendar-focus="payment-${h(item.id)}"`)}${btn('Ver contrato','loan-detail','chevron','sm ghost',`data-id="${h(item.loan_id)}" data-calendar-focus="loan-${h(item.id)}"`)}</div></article>`).join(''):`<div class="calendar-empty">${icon('calendar')}<strong>Nenhum pagamento previsto.</strong><p>Não há parcelas em aberto para esta data.</p>${nextDate?btn('Próximo vencimento','calendar-day','chevron','sm ghost',`data-date="${nextDate}" data-calendar-focus="next-due"`):''}</div>`}</div></section></div>
 <div class="calendar-sync"><span><i class="dot"></i>Atualização automática a cada 30 segundos${lastLoadedAt?` • Sincronizado às ${new Date(lastLoadedAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'})}`:''}</span><p>Novos empréstimos e alterações de datas aparecem aqui. Parcelas quitadas e contratos cancelados saem das marcações.</p></div>`;
}
function refreshCalendar(focusKey){
 const node=document.getElementById('calendar-view');if(route!=='calendar'||!node)return;
 const key=focusKey||document.activeElement?.dataset.calendarFocus;
 node.innerHTML=calendarContent();
 if(key)[...node.querySelectorAll('[data-calendar-focus]')].find(button=>button.dataset.calendarFocus===key)?.focus({preventScroll:true});
}
function selectCalendarDate(date){calendarSelected=date;calendarMonth=date.slice(0,7);refreshCalendar(date);}
function moveCalendarMonth(offset){calendarMonth=shiftMonth(calendarMonth,offset);calendarSelected=dateInMonth(calendarMonth,Number(calendarSelected.slice(-2)));refreshCalendar(offset<0?'prev':'next');}
async function syncCalendar(){
 if(!session||route!=='calendar'||saveBusy||calendarSyncBusy||document.visibilityState==='hidden')return;
 calendarSyncBusy=true;
 try{await load();}catch{const node=document.querySelector('.calendar-sync');if(node)node.innerHTML=`<span class="negative">Não foi possível sincronizar agora. Tentaremos novamente automaticamente.</span>`;}
 finally{calendarSyncBusy=false;}
}

function schedulePage(){return head('Cada vencimento, no seu radar.','Acompanhe as parcelas e registre recebimentos parciais ou integrais.',btn('Exportar CSV','export-schedule','download','ghost'))+`<div class="summary-mini">${[['Em atraso',sum(openItems().filter(i=>i.due_on<today()),'balance')],['Vence hoje',sum(openItems().filter(i=>i.due_on===today()),'balance')],[`Próximos ${preferences.due_window} dias`,sum(openItems().filter(i=>i.due_on>today()&&i.due_on<=dateAdd(today(),preferences.due_window)),'balance')]].map(([l,v])=>`<div class="mini"><small>${l}</small><strong>${money(v)}</strong></div>`).join('')}</div>`+toolbar('Pesquisar cliente ou contrato',[['','Em aberto'],['overdue','Em atraso'],['today','Hoje'],['upcoming','Próximos dias'],['paid','Pagas']])+`<div class="toolbar"><div class="filters"><label>De<input type="date" id="period-from" value="${h(periodFrom)}"></label><label>Até<input type="date" id="period-to" value="${h(periodTo)}"></label>${btn('Limpar período','clear-period','','sm ghost')}</div></div><section class="card" id="results">${scheduleResults()}</section>`;}
function filteredItems(){const q=search.toLowerCase();return model.items.filter(i=>i.loan?.status==='active'&&[i.client?.name,i.loan?.protocol].join(' ').toLowerCase().includes(q)&&(!periodFrom||i.due_on>=periodFrom)&&(!periodTo||i.due_on<=periodTo)&&(filter==='paid'?i.balance===0:filter==='overdue'?i.status==='overdue':filter==='today'?i.due_on===today()&&i.balance>0:filter==='upcoming'?i.balance>0&&i.due_on>=today()&&i.due_on<=dateAdd(today(),preferences.due_window):i.balance>0)).sort((a,b)=>a.due_on.localeCompare(b.due_on));}
function scheduleResults(){const items=filteredItems();return items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Parcela</th><th>Vencimento</th><th>Valor</th><th>Saldo</th><th>Situação</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td>${nameCell(i.client)}</td><td>${i.number}/${i.loan.count}</td><td>${dateLabel(i.due_on)}${i.status==='overdue'?`<div class="negative small">${daysBetween(i.due_on,today())} dia(s) em atraso</div>`:''}</td><td>${money(i.amount_cents)}</td><td>${money(i.balance)}</td><td>${badge(i.status)}</td><td>${i.balance?btn('Receber','payment','plus','sm primary',`data-id="${i.id}"`):btn('Ver contrato','loan-detail','chevron','sm ghost',`data-id="${i.loan_id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="count-text">${items.length} parcela(s) • Saldo ${money(sum(items,'balance'))}</div>`:empty('Nenhuma parcela neste filtro','Ajuste o período ou registre uma nova adesão.');}
function receiptsPage(){return head('Tudo que entrou, registrado.','Recebimentos com data, forma de pagamento e histórico de estornos.',btn('Exportar CSV','export-receipts','download','ghost'))+toolbar('Pesquisar cliente ou contrato',[['','Confirmados'],['voided','Estornados']])+`<section class="card" id="results">${receiptsResults()}</section>`;}
function receiptsResults(){const q=search.toLowerCase();const rows=model.receipts.map(r=>({...r,item:model.items.find(i=>i.id===r.installment_id)})).filter(r=>(filter==='voided'?r.voided_at:!r.voided_at)&&[r.item?.client?.name,r.item?.loan?.protocol].join(' ').toLowerCase().includes(q)).sort((a,b)=>b.paid_on.localeCompare(a.paid_on));return rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Cliente</th><th>Contrato / parcela</th><th>Data</th><th>Valor</th><th>Forma</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${nameCell(r.item?.client)}</td><td>${h(r.item?.loan?.protocol)}<div class="muted small">Parcela ${r.item?.number}/${r.item?.loan?.count}</div></td><td>${dateLabel(r.paid_on)}</td><td>${money(r.amount_cents)}${r.voided_at?'<div class="negative small">Estornado</div>':''}</td><td>${h(r.method)}${r.notes?`<div class="muted small">${h(r.notes)}</div>`:''}</td><td>${r.voided_at?`<small class="muted">${h(r.void_reason)}</small>`:btn('Estornar','reverse-payment','refresh','sm danger ghost',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="count-text">${rows.length} recebimento(s) • ${money(sum(rows,'amount_cents'))}</div>`:empty('Nenhum recebimento neste filtro','Os pagamentos registrados nas parcelas aparecerão aqui.');}
function field(label,name,value='',type='text',attrs='',span=''){return `<label class="${span}">${label}<input name="${name}" type="${type}" value="${h(value)}" ${attrs}></label>`;}
function clientFields(c={}){return `<div class="form-grid" data-address-fields>${field('Nome completo *','name',c.name,'text','required minlength="3" maxlength="160" autocomplete="name"','span2')}${field('CPF *','cpf',cpfFormat(c.cpf),'text','required inputmode="numeric" maxlength="14" placeholder="000.000.000-00" data-mask="cpf"')}${field('Telefone / WhatsApp *','phone',c.phone?phoneFormat(c.phone):'+55 ','tel','required autocomplete="tel" placeholder="+55 79 99999-0001" maxlength="19" data-mask="phone"')}${field('E-mail','email',c.email,'email','autocomplete="email"')}${field('Data de nascimento','birth_date',c.birth_date,'date',`max="${today()}"`)}${cep.field(c.cep)}${field('Estado / UF','state',c.state,'text','maxlength="2" placeholder="SE"')}${field('Endereço / rua','street',c.street,'text','autocomplete="address-line1"','span2')}${field('Número','number',c.number)}${field('Complemento','complement',c.complement)}${field('Bairro','district',c.district)}${field('Cidade','city',c.city)}<label class="span2">Observações<textarea name="notes" rows="3" placeholder="Informações úteis para o atendimento">${h(c.notes)}</textarea></label></div>`;}
function readClient(form){const f=new FormData(form),c={};for(const key of ['name','cpf','phone','email','birth_date','cep','street','number','complement','district','city','state','notes'])c[key]=String(f.get(key)||'').trim();if(!validCPF(c.cpf))throw new Error('Informe um CPF válido.');c.cpf=digits(c.cpf);c.cep=digits(c.cep);if(c.cep&&c.cep.length!==8)throw new Error('O CEP precisa ter 8 dígitos.');c.phone=normalizePhone(c.phone);c.state=c.state.toUpperCase();if(c.state&&!['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'].includes(c.state))throw new Error('Informe uma UF válida.');return c;}
function clientPage(){const id=location.hash.split('/')[2],c=model.clients.find(c=>c.id===id)||{};return head(c.id?'Editar cadastro.':'Um novo relacionamento.','Os dados ficam registrados no banco privado da JK CRED.',link('Voltar para clientes','#/clients','chevron','ghost'))+`<form id="client-form" data-id="${h(c.id||'')}" class="card" style="max-width:850px"><section class="form-section"><div class="step-label">${icon('users')}Dados do cliente</div><p class="section-caption" style="margin-top:10px">Nome, CPF e WhatsApp são obrigatórios. Os demais dados podem ser completados depois.</p>${clientFields(c)}${c.id?`<label style="margin-top:18px">Situação<select name="archived"><option value="false" ${!c.archived?'selected':''}>Ativo</option><option value="true" ${c.archived?'selected':''}>Arquivado (mantém todo o histórico)</option></select></label>`:''}<div class="form-footer"><p>* Campos obrigatórios</p><button class="btn primary" type="submit">${icon('check')}Salvar cliente</button></div><div class="error-inline" id="form-error" role="alert"></div></section></form>`;}
function newBuilder(simulation=false){const seed=model.clients.find(c=>c.id===new URLSearchParams(location.hash.split('?')[1]||'').get('client'));return {simulation,mode:seed?'existing':model.clients.filter(c=>!c.archived).length?'existing':'new',client_id:seed?.id||'',principal:'200.00',rate:(preferences.default_rate_bps/100).toFixed(2),fee:(preferences.default_fee_cents/100).toFixed(2),count:3,first:dateAdd(today(),15),interval:'15',customInterval:15,released_on:today(),name:'',phone:'+55 ',cpf:'',city:'',district:'',notes:'',dates:[],request_id:crypto.randomUUID()};}
function proposalLoan(id){const loan=model.loans.find(loan=>loan.id===id);if(!loan)throw new Error('Contrato não encontrado. Atualize os dados e tente novamente.');return loan;}
function proposalClient(){
 const b=builder;
 if(b.simulation)return {name:b.name,phone:b.phone,cpf:b.cpf,city:b.city,district:b.district};
 if(b.mode==='existing')return model.clients.find(client=>client.id===b.client_id)||{};
 return Object.fromEntries(['name','phone','cpf','city','state','district'].map(key=>[key,document.querySelector(`#adhesion-form [name=${key}]`)?.value||'']));
}
function proposalData(loanId){
 if(loanId)return adhesionProposal(proposalLoan(loanId));
 const b=builder,c=calculate(decimalInt(b.principal),decimalInt(b.rate),decimalInt(b.fee),Number(b.count));
 if(!b.dates.length)b.dates=scheduleDates(b.first,Number(b.count),b.interval==='custom'?b.customInterval:b.interval);
 const client=proposalClient(),name=client.name;
 return {name,client,calculation:c,dates:[...b.dates],issuedOn:b.simulation?today():b.released_on,kind:b.simulation?'simulation':'adhesion'};
}
function proposalHTML(loanId,artId='proposal'){try{return `<article class="proposal proposal-art" id="${h(artId)}">${proposalSVG(proposalData(loanId))}</article>`;}catch(error){return `<article class="proposal-error">${empty('Confira os dados para gerar a imagem',h(friendly(error)))}</article>`;}}
let jpegCache={svg:'',promise:null};
function currentJPEG(loanId){
 if(!loanId)builderLoan();
 const data=proposalData(loanId),svg=proposalSVG(data);
 if(jpegCache.svg!==svg){jpegCache={svg,promise:proposalJPEG(svg,proposalFilename(data.name,data.issuedOn,data.kind))};jpegCache.promise.catch(()=>{if(jpegCache.svg===svg)jpegCache={svg:'',promise:null};});}
 return jpegCache.promise;
}
async function shareJPEG(loanId){
 const {text:message,title}=proposalMessage(loanId),file=await currentJPEG(loanId);
 if(navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title,text:message});toast('Compartilhamento concluído.');return;}catch(error){if(error.name==='AbortError')return;if(error.name!=='NotAllowedError'&&error.name!=='NotSupportedError')throw error;}}
 downloadProposal(file);
 const data=loanId?`data-loan-id="${h(loanId)}"`:'';
 showModal('JPEG pronto para enviar','Seu navegador baixou a imagem. Anexe o arquivo à conversa no WhatsApp.',`<p class="muted small">Arquivo: <strong>${h(file.name)}</strong></p><div class="actions" style="margin-top:20px">${btn('Abrir WhatsApp com o texto','whatsapp-proposal','whatsapp','whatsapp',data)}${btn('Copiar mensagem','copy-proposal','copy','ghost',data)}</div><p class="note">O link do WhatsApp prepara o texto. Para enviar a imagem, selecione o JPEG baixado como anexo na conversa.</p>`);
}
function appearanceSettings(){const theme=window.JKTheme?.get()||'dark';return `<section class="card appearance-card"><div class="card-head"><div><h2>Aparência do painel</h2><p>Escolha o modo mais confortável para trabalhar</p></div>${icon('settings')}</div><div class="card-body"><div class="theme-options" role="group" aria-label="Modo de aparência"><button type="button" class="theme-option" data-action="theme" data-theme-option="dark" aria-pressed="${theme==='dark'}"><span class="theme-swatch swatch-dark"><i></i><b></b><b></b></span><span><strong>Modo escuro</strong><small>Preto, dourado e tons suaves</small></span></button><button type="button" class="theme-option" data-action="theme" data-theme-option="light" aria-pressed="${theme==='light'}"><span class="theme-swatch swatch-light"><i></i><b></b><b></b></span><span><strong>Modo claro</strong><small>Fundo claro e contraste reforçado</small></span></button></div><p class="appearance-note">A escolha é lembrada neste navegador. A arte enviada ao cliente mantém o estilo preto e dourado da JK CRED.</p></div></section>`;}
function builderPage(simulation){if(!builder||builder.simulation!==simulation)builder=newBuilder(simulation);const b=builder;return head(simulation?'Uma proposta que fala por você.':'Uma adesão. Tudo conectado.',simulation?'Simule, ajuste os vencimentos e compartilhe uma proposta clara.':'Cadastre o cliente, registre o contrato e prepare a confirmação.',simulation?link('Registrar adesão','#/adhesion','plus','primary'):link('Abrir calculadora','#/simulation','calc','ghost'))+`<div class="builder"><form id="${simulation?'simulation-form':'adhesion-form'}" class="builder-form"><section class="card"><div class="form-section"><div class="step-label"><b>01</b>${simulation?'Para quem é a proposta?':'Selecione ou cadastre o cliente'}</div>${simulation?`<div class="form-grid">${field('Nome do cliente','sim_name',b.name,'text','placeholder="Nome do cliente" maxlength="160"','span2')}${field('WhatsApp (opcional)','sim_phone',b.phone,'tel','placeholder="+55 79 99999-0001" data-mask="phone" maxlength="19"','span2')}</div><details class="proposal-client-extra"><summary>Dados complementares (opcional)</summary><div class="form-grid">${field('CPF','sim_cpf',b.cpf,'text','data-mask="cpf" maxlength="14" placeholder="000.000.000-00"')}${field('Cidade','sim_city',b.city,'text','maxlength="100" placeholder="Ex.: Aracaju"')}${field('Bairro','sim_district',b.district,'text','maxlength="100" placeholder="Ex.: Centro"','span2')}</div></details>`:`<div class="segments"><button type="button" data-action="client-mode" data-mode="existing" class="${b.mode==='existing'?'active':''}">Cliente cadastrado</button><button type="button" data-action="client-mode" data-mode="new" class="${b.mode==='new'?'active':''}">Novo cliente</button></div><div id="builder-client">${b.mode==='new'?clientFields(b.client||{}):`<label style="margin-top:20px">Cliente *<select name="client_id" required><option value="">Selecione o cliente</option>${model.clients.filter(c=>!c.archived).sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${c.id}" ${b.client_id===c.id?'selected':''}>${h(c.name)} • ${cpfFormat(c.cpf)}</option>`).join('')}</select></label>${!model.clients.filter(c=>!c.archived).length?'<p class="note">Nenhum cliente ativo. Selecione “Novo cliente” para cadastrar.</p>':''}`}</div>`}</div></section><section class="card"><div class="form-section"><div class="step-label"><b>02</b>Condições do empréstimo</div><div class="form-grid">${field('Valor liberado (R$) *','principal',b.principal,'number','required min="0.01" max="100000000" step="0.01"')}${field('Taxa de juros (%) *','rate',b.rate,'number','required min="0" max="1000" step="0.01"')}${field('Quantidade de parcelas *','count',b.count,'number','required min="1" max="120" step="1"')}${field('Acréscimo por parcela adicional (R$)','fee',b.fee,'number','required min="0" max="1000000" step="0.01"')}</div><p class="note">${icon('calc')} &nbsp; Valor + juros + acréscimo × (parcelas − 1).<br>A primeira parcela não gera acréscimo. O total é dividido entre as parcelas; eventuais centavos ficam na última.</p></div><div class="form-section"><div class="step-label"><b>03</b>Datas e vencimentos</div><div class="form-grid">${field('Data da liberação *','released_on',b.released_on,'date',`required max="${today()}"`)}${field('Primeiro vencimento *','first',b.first,'date','required')}<label>Intervalo entre parcelas<select name="interval">${[['7','Semanal • 7 dias'],['15','A cada 15 dias'],['21','A cada 21 dias'],['30','A cada 30 dias'],['monthly','Mensal • mesmo dia'],['custom','Personalizado']].map(([k,l])=>`<option value="${k}" ${b.interval===k?'selected':''}>${l}</option>`).join('')}</select></label><label id="custom-interval" ${b.interval!=='custom'?'hidden':''}>Intervalo em dias<input name="customInterval" type="number" value="${b.customInterval}" min="1" max="365" step="1"></label></div><p class="note">Você pode ajustar cada vencimento abaixo. A opção mensal mantém o dia de referência, respeitando o último dia de cada mês.</p><div class="schedule-editor" id="schedule-editor"></div></div>${!simulation?`<div class="form-section"><label>Observações do contrato<textarea name="loan_notes" rows="3" placeholder="Condições combinadas, anotações internas…">${h(b.notes)}</textarea></label></div>`:''}</section>${simulation?'<p class="small muted">Simular não cria cliente nem contrato no banco.</p>':`<div id="adhesion-cash-preview"></div><div class="form-footer"><p>Cliente, contrato e saída do caixa são salvos juntos.</p><button class="btn primary" type="submit">${icon('check')}Confirmar adesão</button></div>`}<div class="error-inline" id="builder-error" role="alert"></div></form><div class="preview-area"><div class="preview-label"><span>${icon('shield')} &nbsp; ${simulation?'PRÉVIA DA PROPOSTA':'PRÉVIA DA ADESÃO'}</span><span>Pronta para compartilhar</span></div><div id="proposal-container">${proposalHTML()}</div><div class="preview-actions">${btn('Baixar JPEG','download-jpeg','download','primary')}${btn('Compartilhar JPEG','share-jpeg','arrow','whatsapp')}${btn('Copiar mensagem','copy-proposal','copy','ghost')}${btn('WhatsApp (texto)','whatsapp-proposal','whatsapp','ghost')}${btn('Imprimir / PDF','print','print','ghost')}${btn('Ampliar arte','proposal-focus','search','ghost')}</div><p class="small muted" style="font-size:10px;margin-top:13px">Baixe o JPEG ou use o compartilhamento do dispositivo. Se o navegador não compartilhar arquivos, o JPEG será baixado para você anexar no WhatsApp.</p></div></div>`;}
function syncBuilder(target){if(!builder)return;const b=builder,name=target.name;if(name==='sim_name')b.name=target.value;else if(name==='sim_phone')b.phone=target.value;else if(name==='sim_cpf')b.cpf=target.value;else if(name==='sim_city')b.city=target.value;else if(name==='sim_district')b.district=target.value;else if(name==='loan_notes')b.notes=target.value;else if(['principal','rate','fee','count','first','interval','released_on','client_id','customInterval'].includes(name))b[name]=target.value;if(['count','first','interval','customInterval'].includes(name)){try{b.dates=scheduleDates(b.first,Number(b.count),b.interval==='custom'?Number(b.customInterval):b.interval);}catch{b.dates=[];}}if(target.dataset.dateIndex!==undefined)b.dates[Number(target.dataset.dateIndex)]=target.value;const custom=document.getElementById('custom-interval');if(custom)custom.hidden=b.interval!=='custom';updatePreview(!target.hasAttribute('data-date-index'));}
function updateCashPreview(){if(route!=='adhesion'||!builder)return;const node=document.getElementById('adhesion-cash-preview');if(!node)return;try{const principal=decimalInt(builder.principal),key=principal+'/'+cashRecords.account.balance_cents;if(node.dataset.cashPreview!==key){node.innerHTML=cash.loanPreview(principal);node.dataset.cashPreview=key;}const button=document.querySelector('#adhesion-form [type=submit]');if(button)button.disabled=saveBusy;}catch{node.innerHTML='';}}
function updatePreview(updateDates=true){updateCashPreview();const container=document.getElementById('proposal-container');if(container)container.innerHTML=proposalHTML();if(updateDates){const editor=document.getElementById('schedule-editor');if(editor){try{const c=calculate(decimalInt(builder.principal),decimalInt(builder.rate),decimalInt(builder.fee),Number(builder.count));editor.innerHTML=c.amounts.map((a,i)=>`<div class="schedule-line"><span>${i+1}/${c.count}</span><label><span class="visually-hidden">Vencimento da parcela ${i+1}</span><input type="date" data-date-index="${i}" value="${h(builder.dates[i]||'')}" required></label><strong>${money(a)}</strong></div>`).join('');}catch{editor.innerHTML='';}}}}
function builderLoan(){const b=builder,c=calculate(decimalInt(b.principal),decimalInt(b.rate),decimalInt(b.fee),Number(b.count));if(b.dates.length!==c.count)throw new Error('Confira as datas de todas as parcelas.');let prev=b.released_on;for(let i=0;i<b.dates.length;i++){const d=b.dates[i];if(!d||d<prev||(i>0&&d===prev))throw new Error('Os vencimentos devem estar em ordem crescente, a partir da data da liberação.');prev=d;}return {principal_cents:c.principal,rate_bps:c.rate,fee_cents:c.fee,count:c.count,interest_cents:c.interest,total_cents:c.total,released_on:b.released_on,dates:[...b.dates],notes:b.notes};}
function proposalMessage(loanId){
 if(loanId){const loan=proposalLoan(loanId);return {text:messageFor(loan.client,loan,loan.installments,preferences.message_template),phone:loan.client?.phone,title:'Adesão concluída JK CRED'};}
 const loan=builderLoan(),calculation=calculate(loan.principal_cents,loan.rate_bps,loan.fee_cents,loan.count),client=proposalClient();
 if(!builder.simulation)loan.protocol='A confirmar após o registro';
 return {text:messageFor(client||{},loan,loan.dates.map((due_on,i)=>({due_on,amount_cents:calculation.amounts[i]})),preferences.message_template,builder.simulation),phone:client?.phone,title:builder.simulation?'Simulação personalizada JK CRED':'Adesão concluída JK CRED'};
}
function settingsPage(){return head('Do seu jeito, em cada detalhe.','Defina os padrões das simulações e personalize a confirmação de adesão.')+appearanceSettings()+`<form id="settings-form"><div class="settings-grid"><section class="card"><div class="card-head"><div><h2>Padrões financeiros</h2><p>Aplicados em novas simulações</p></div>${icon('calc')}</div><div class="card-body">${field('Juros padrão (%)','default_rate',(preferences.default_rate_bps/100).toFixed(2),'number','min="0" max="1000" step="0.01" required')}${field('Acréscimo padrão (R$)','default_fee',(preferences.default_fee_cents/100).toFixed(2),'number','min="0" max="1000000" step="0.01" required')}${field('Alerta de proximidade (dias)','due_window',preferences.due_window,'number','min="1" max="90" step="1" required')}<p class="note">Alterar estes padrões não modifica contratos já registrados.</p></div></section><section class="card"><div class="card-head"><div><h2>Mensagem de adesão</h2><p>Os campos entre chaves são preenchidos automaticamente</p></div>${icon('mail')}</div><div class="card-body"><label>Modelo da mensagem<textarea name="message_template" rows="21">${h(preferences.message_template||DEFAULT_TEMPLATE)}</textarea></label><div class="token-list">${['nome','contrato','situacao','valor','data','taxa','juros','acrescimo','extras','efetiva','parcelas','vencimentos','retornos','total'].map(t=>`<code>{${t}}</code>`).join('')}</div><div class="actions" style="margin-top:18px">${btn('Restaurar texto padrão','restore-template','refresh','sm ghost')}</div></div></section></div><div class="form-footer"><p>As alterações ficam disponíveis para toda a administração.</p><button class="btn primary" type="submit">${icon('check')}Salvar preferências</button></div><div id="form-error" class="error-inline" role="alert"></div></form><section class="card" style="margin-top:30px"><div class="card-head"><div><h2>Histórico de atividade</h2><p>As últimas 30 alterações no painel</p></div>${icon('clock')}</div><div class="card-body">${events.length?events.map(e=>`<div class="receipt-row"><p>${h(e.action)}${e.details?.reason?`<br><small>${h(e.details.reason)}</small>`:''}</p><small>${new Date(e.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})}</small></div>`).join(''):empty('Nenhuma atividade registrada','As alterações serão registradas automaticamente.')}</div></section>`;}
function showModal(title,subtitle,body){modal.innerHTML=`<div class="modal-head"><div><h2>${h(title)}</h2><p>${h(subtitle||'')}</p></div>${btn('<span class="visually-hidden">Fechar janela</span>','close','close','icon-only ghost')}</div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
function clientDetail(id){const c=model.clients.find(c=>c.id===id);if(!c)return;const loans=model.loans.filter(l=>l.client_id===id);showModal(c.name,'Ficha do cliente',`<div class="detail-grid">${[['CPF',cpfFormat(c.cpf)],['Telefone',phoneFormat(c.phone)],['E-mail',c.email||'—'],['Nascimento',dateLabel(c.birth_date)],['CEP',c.cep||'—'],['Cidade / UF',[c.city,c.state].filter(Boolean).join(' / ')||'—'],['Endereço',[c.street,c.number,c.complement,c.district].filter(Boolean).join(', ')||'—'],['Observações',c.notes||'—'],['Saldo em aberto',money(sum(loans.filter(l=>l.status==='active'),'balance'))]].map(([k,v])=>`<div><small>${k}</small><strong>${h(v)}</strong></div>`).join('')}</div><div class="actions">${link('Editar cadastro','#/client/'+id,'edit','ghost')}${link('Novo empréstimo','#/adhesion?client='+id,'plus','primary')}</div><h3 style="margin:25px 0 15px">Histórico de contratos</h3>${loans.length?loanTable(loans):empty('Nenhum contrato registrado','Este cliente ainda não tem empréstimos.')}`);}
function loanDetail(id){selectedLoan=id;const l=model.loans.find(l=>l.id===id);if(!l)return;const rec=model.receipts.filter(r=>l.installments.some(i=>i.id===r.installment_id)).sort((a,b)=>b.created_at.localeCompare(a.created_at));showModal(l.protocol,l.client?.name,`<div class="summary-mini"><div class="mini"><small>Valor liberado</small><strong>${money(l.principal_cents)}</strong></div><div class="mini"><small>Recebido</small><strong>${money(l.paid)}</strong></div><div class="mini"><small>Saldo</small><strong>${money(l.status==='cancelled'?0:l.balance)}</strong></div></div><div class="detail-grid">${[['Liberação',dateLabel(l.released_on)],['Juros',`${l.rate_bps/100}% • ${money(l.interest_cents)}`],['Acréscimos',`${l.count-1} × ${money(l.fee_cents)}`],['Total contratado',money(l.total_cents)],['Situação',l.status==='cancelled'?'Cancelado':l.balance===0?'Quitado':'Ativo'],['Observações',l.notes||'—']].map(([k,v])=>`<div><small>${k}</small><strong>${h(v)}</strong></div>`).join('')}</div><div class="actions">${btn('Mensagem de adesão','message','copy','ghost',`data-id="${id}"`)}${l.status==='active'?btn('Alterar vencimentos','reschedule','calendar','ghost',`data-id="${id}"`):''}${l.status==='active'&&!l.paid?btn('Cancelar contrato','cancel-loan','close','ghost danger',`data-id="${id}"`):''}</div><h3 style="margin:26px 0 13px">Parcelas</h3><div class="table-wrap"><table class="data-table"><thead><tr><th>Parcela</th><th>Vencimento</th><th>Valor / saldo</th><th>Situação</th><th></th></tr></thead><tbody>${l.installments.map(i=>`<tr><td>${i.number}/${l.count}</td><td>${dateLabel(i.due_on)}</td><td>${money(i.amount_cents)}<div class="muted small">Saldo: ${money(i.balance)}</div></td><td>${badge(i.status)}</td><td>${l.status==='active'&&i.balance?btn('Receber','payment','plus','sm primary',`data-id="${i.id}"`):''}</td></tr>`).join('')}</tbody></table></div><h3 style="margin:26px 0 10px">Recebimentos</h3>${rec.length?rec.map(r=>`<div class="receipt-row"><div><p>${money(r.amount_cents)} • ${h(r.method)} ${r.voided_at?'<span class="negative">• Estornado</span>':''}</p><small>${dateLabel(r.paid_on)} • Parcela ${l.installments.find(i=>i.id===r.installment_id)?.number}${r.notes?' • '+h(r.notes):''}${r.voided_at?' • '+h(r.void_reason):''}</small></div>${!r.voided_at?btn('Estornar','reverse-payment','refresh','sm ghost danger',`data-id="${r.id}"`):''}</div>`).join(''):'<p class="muted small">Nenhum pagamento registrado.</p>'}`);}
function adhesionMessage(id){
 const loan=proposalLoan(id),data=`data-loan-id="${h(id)}"`;
 currentMessage=messageFor(loan.client,loan,loan.installments,preferences.message_template);
 showModal('Adesão registrada com sucesso!','Confira os dados e compartilhe a confirmação.',`<div class="note" style="margin-top:0">${icon('check')} &nbsp; Cliente, contrato e parcelas salvos no banco.</div><details class="adhesion-artwork"><summary>Ver JPEG da adesão</summary><div>${proposalHTML(id,'adhesion-proposal')}</div></details><pre class="message-text">${h(currentMessage)}</pre><div class="actions">${btn('Baixar JPEG','download-jpeg','download','primary',data)}${btn('Compartilhar JPEG','share-jpeg','arrow','whatsapp',data)}${btn('Copiar mensagem completa','copy-message','copy','ghost')}<a class="btn whatsapp" href="${h(whatsApp(loan.client.phone,currentMessage))}" target="_blank" rel="noopener noreferrer">${icon('whatsapp')}Abrir WhatsApp</a>${btn('Ver contrato','loan-detail','chevron','ghost',`data-id="${h(id)}"`)}</div><p class="muted small" style="margin-top:15px;font-size:10px">O JPEG contém os valores e vencimentos do contrato registrado. O WhatsApp abre com a mensagem pronta; você decide quando enviar.</p>`);
}
function paymentModal(id){const i=model.items.find(i=>i.id===id);if(!i)return;showModal('Registrar recebimento',`${i.client?.name} • Parcela ${i.number}/${i.loan.count}`,`<div class="summary-mini"><div class="mini"><small>Valor da parcela</small><strong>${money(i.amount_cents)}</strong></div><div class="mini"><small>Já recebido</small><strong>${money(i.paid)}</strong></div><div class="mini"><small>Saldo</small><strong>${money(i.balance)}</strong></div></div><form id="payment-form" data-id="${id}" data-request="${crypto.randomUUID()}"><div class="form-grid">${field('Valor recebido (R$) *','amount',(i.balance/100).toFixed(2),'number',`required min="0.01" max="${(i.balance/100).toFixed(2)}" step="0.01"`)}${field('Data do recebimento *','paid_on',today(),'date',`required min="${i.loan.released_on}" max="${today()}"`)}<label>Forma de pagamento<select name="method"><option value="pix">Pix</option><option value="dinheiro">Dinheiro</option><option value="transferencia">Transferência</option><option value="outro">Outro</option></select></label>${field('Observações','notes','')}</div>${society.paymentPreview(i.balance)}<div class="note">O valor pode ser parcial. O saldo restante continua em aberto até a quitação.</div><div class="actions" style="margin-top:20px"><button class="btn primary" type="submit">${icon('check')}Confirmar recebimento</button>${btn('Voltar ao contrato','loan-detail','chevron','ghost',`data-id="${i.loan_id}"`)}</div><div class="error-inline" id="modal-error" role="alert"></div></form>`);}
function reasonModal(action,id){const isReverse=action==='reverse-payment';showModal(isReverse?'Estornar pagamento':'Cancelar contrato',isReverse?'O recebimento ficará no histórico, marcado como estornado.':'O contrato permanece no histórico e sai dos totais da carteira.',`<form id="reason-form" data-id="${id}" data-kind="${action}"><p class="note" style="margin-top:0">${isReverse?'Se este pagamento entrou no caixa, seu estorno também retira o valor do caixa.':'Se a liberação foi registrada no caixa, o cancelamento devolve o valor liberado ao saldo.'}</p><label>Motivo *<textarea name="reason" rows="3" required minlength="3" placeholder="Descreva o motivo da alteração"></textarea></label><div class="actions" style="margin-top:20px"><button class="btn danger" type="submit">${icon('check')}${isReverse?'Confirmar estorno':'Confirmar cancelamento'}</button>${btn('Voltar','close','','ghost')}</div><div class="error-inline" id="modal-error" role="alert"></div></form>`);}
function rescheduleModal(id){const l=model.loans.find(l=>l.id===id);if(!l)return;showModal('Ajustar vencimentos',`${l.protocol} • Os valores das parcelas são mantidos.`,`<form id="reschedule-form" data-id="${id}"><div class="form-grid">${l.installments.map(i=>field(`Parcela ${i.number}/${l.count} • ${money(i.amount_cents)}`,'due_'+i.number,i.due_on,'date','required')).join('')}<label class="span2">Motivo da alteração *<textarea name="reason" rows="2" required minlength="3"></textarea></label></div><button class="btn primary" type="submit">${icon('check')}Salvar vencimentos</button><div class="error-inline" id="modal-error" role="alert"></div></form>`);}
function render(){if(!session)return;cep.cancel();const next=location.hash.slice(2).split(/[/?]/)[0]||'dashboard';if(next!==route){filter='';search='';periodFrom='';periodTo='';if(!['simulation','adhesion'].includes(next))builder=null;if(next==='simulation'&&builder&&!builder.simulation)builder=null;if(next==='adhesion'&&builder?.simulation){const previous=builder;builder=newBuilder(false);for(const key of ['principal','rate','fee','count','first','interval','customInterval','released_on','dates'])builder[key]=previous[key];if(previous.name){builder.mode='new';builder.client={name:previous.name,phone:previous.phone,cpf:previous.cpf,city:previous.city,district:previous.district};}}}
 route=next in titles?next:'dashboard';if(modal.open)modal.close();const pages={dashboard,cash:()=>cash.render(),society:()=>society.render(),calendar:calendarPage,clients:clientsPage,loans:loansPage,schedule:schedulePage,receipts:receiptsPage,simulation:()=>builderPage(true),adhesion:()=>builderPage(false),settings:settingsPage,client:clientPage};el.innerHTML=shell(pages[route]());if(['adhesion','simulation'].includes(route))updatePreview();document.title=`${titles[route]} — JK CRED`;window.scrollTo(0,0);if(route==='calendar'&&Date.now()-lastLoadedAt>5000)syncCalendar();if(route==='society'&&Date.now()-lastLoadedAt>5000)syncSociety();if(['cash','dashboard'].includes(route)&&Date.now()-lastLoadedAt>5000)syncCash();}
function updateResults(){const node=document.getElementById('results');if(node)node.innerHTML=({clients:clientsResults,loans:loansResults,schedule:scheduleResults,receipts:receiptsResults}[route]||(()=>''))();}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Texto completo copiado.');}catch{showModal('Copie a mensagem','Selecione o texto abaixo e copie.',`<textarea rows="18" readonly>${h(text)}</textarea>`);modal.querySelector('textarea').select();}}
function exportData(action){let rows,filename;if(action==='export-clients'){rows=[['Nome','CPF','Telefone','E-mail','Nascimento','CEP','Endereço','Número','Complemento','Bairro','Cidade','UF','Saldo devedor'],...model.clients.map(c=>[c.name,cpfFormat(c.cpf),c.phone,c.email,dateLabel(c.birth_date),c.cep,c.street,c.number,c.complement,c.district,c.city,c.state,(sum(activeLoans().filter(l=>l.client_id===c.id),'balance')/100).toFixed(2)])];filename='clientes';}else if(action==='export-loans'){rows=[['Contrato','Cliente','Liberação','Valor liberado','Juros %','Acréscimo adicional','Parcelas','Total','Recebido','Saldo','Situação'],...model.loans.map(l=>[l.protocol,l.client?.name,dateLabel(l.released_on),(l.principal_cents/100).toFixed(2),l.rate_bps/100,(l.fee_cents/100).toFixed(2),l.count,(l.total_cents/100).toFixed(2),(l.paid/100).toFixed(2),(l.status==='cancelled'?0:l.balance/100).toFixed(2),l.status==='cancelled'?'Cancelado':l.balance===0?'Quitado':'Em aberto'])];filename='emprestimos';}else if(action==='export-schedule'){rows=[['Cliente','Contrato','Parcela','Vencimento','Valor','Recebido','Saldo','Situação'],...filteredItems().map(i=>[i.client?.name,i.loan.protocol,`${i.number}/${i.loan.count}`,dateLabel(i.due_on),(i.amount_cents/100).toFixed(2),(i.paid/100).toFixed(2),(i.balance/100).toFixed(2),statusLabels[i.status]])];filename='vencimentos';}else{rows=[['Cliente','Contrato','Parcela','Data','Valor','Forma','Observações','Estornado','Motivo'],...model.receipts.map(r=>{const i=model.items.find(i=>i.id===r.installment_id);return [i?.client?.name,i?.loan?.protocol,i?.number,dateLabel(r.paid_on),(r.amount_cents/100).toFixed(2),r.method,r.notes,r.voided_at?'Sim':'Não',r.void_reason];})];filename='recebimentos';}const url=URL.createObjectURL(new Blob([csv(rows)],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=`jk-cred-${filename}-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
document.addEventListener('click',async event=>{if(event.target.closest('.sidebar .nav a'))document.querySelector('.sidebar')?.classList.remove('open');const node=event.target.closest('[data-action]');if(!node)return;const {action,id,loanId}=node.dataset;try{
 if(action==='cep-lookup'){await cep.search(node);return;}
 if(action.startsWith('cash-')){if(route==='adhesion'&&builder?.mode==='new'){const form=document.getElementById('adhesion-form');if(form)builder.client=Object.fromEntries(new FormData(form));}await cash.action(action,node);return;}
 if(action.startsWith('society-')){await society.action(action,node);return;}
 if(action==='close'){modal.close();return;}
 if(action==='menu'){document.querySelector('.sidebar')?.classList.toggle('open');return;}
 if(action==='refresh'){node.disabled=true;await load();render();toast('Dados atualizados.');return;}
 if(action==='calendar-prev'){moveCalendarMonth(-1);return;}
 if(action==='calendar-next'){moveCalendarMonth(1);return;}
 if(action==='calendar-today'){selectCalendarDate(today());return;}
 if(action==='calendar-day'){selectCalendarDate(node.dataset.date);return;}
 if(action==='filter'){filter=node.dataset.filter;document.querySelectorAll('[data-action=filter]').forEach(n=>n.classList.toggle('active',n.dataset.filter===filter));updateResults();return;}
 if(action==='clear-period'){periodFrom='';periodTo='';document.getElementById('period-from').value='';document.getElementById('period-to').value='';updateResults();return;}
 if(action==='client-detail'){clientDetail(id);return;}
 if(action==='loan-detail'){loanDetail(id);return;}
 if(action==='payment'){paymentModal(id);return;}
 if(action==='message'){adhesionMessage(id);return;}
 if(action==='reschedule'){rescheduleModal(id);return;}
 if(action==='reverse-payment'||action==='cancel-loan'){reasonModal(action,id);return;}
 if(action==='client-mode'){if(builder.mode==='new'){const form=document.getElementById('adhesion-form');builder.client={};for(const [key,value]of new FormData(form))builder.client[key]=value;}builder.mode=node.dataset.mode;cep.cancel();el.innerHTML=shell(builderPage(false));updatePreview();return;}
 if(action==='copy-message'){await copy(currentMessage);return;}
 if(action==='theme'){window.JKTheme.set(node.dataset.themeOption);toast(node.dataset.themeOption==='light'?'Modo claro ativado.':'Modo escuro ativado.');return;}
 if(action==='download-jpeg'){node.disabled=true;try{downloadProposal(await currentJPEG(loanId));toast('JPEG baixado.');}finally{node.disabled=false;}return;}
 if(action==='share-jpeg'){node.disabled=true;try{await shareJPEG(loanId);}finally{node.disabled=false;}return;}
 if(action==='copy-proposal'){await copy(proposalMessage(loanId).text);return;}
 if(action==='whatsapp-proposal'){const m=proposalMessage(loanId);const url=whatsApp(m.phone,m.text);window.open(url,'_blank','noopener,noreferrer');return;}
 if(action==='print'){document.body.classList.add('printing');window.print();document.body.classList.remove('printing');return;}
 if(action==='proposal-focus'){builderLoan();showModal(builder.simulation?'Simulação personalizada JK CRED':'Adesão concluída JK CRED',builder.simulation?'A imagem é preenchida com os dados da proposta.':'A imagem é preenchida com os dados da adesão.',proposalHTML(undefined,'proposal-enlarged')+`<div class="actions" style="margin-top:20px">${btn('Baixar JPEG','download-jpeg','download','primary')}${btn('Compartilhar JPEG','share-jpeg','arrow','whatsapp')}${btn('Copiar mensagem','copy-proposal','copy','ghost')}</div>`);return;}
 if(action==='restore-template'){document.querySelector('[name=message_template]').value=DEFAULT_TEMPLATE;return;}
 if(action.startsWith('export-')){exportData(action);return;}
 }catch(error){toast(friendly(error),true);node.disabled=false;}});
document.addEventListener('input',event=>{const target=event.target;if(cep.input(target)||cash.input(target)||society.input(target))return;if(target.dataset.mask==='cpf')target.value=cpfFormat(target.value);if(target.dataset.mask==='cep')target.value=digits(target.value).slice(0,8).replace(/(\d{5})(\d)/,'$1-$2');if(target.dataset.mask==='phone'){let p=digits(target.value);if(p.startsWith('55'))p=p.slice(2);p=p.slice(0,11);const rest=p.slice(2);target.value='+55'+(p?' '+p.slice(0,2):' ')+(rest?' '+(rest.length>4?rest.slice(0,-4)+'-'+rest.slice(-4):rest):'');}if(target.id==='search'){search=target.value;updateResults();return;}if(target.closest('#simulation-form,#adhesion-form'))syncBuilder(target);});
document.addEventListener('change',event=>{const target=event.target;if(cep.input(target)||cash.input(target)||society.input(target))return;if(target.id==='period-from'||target.id==='period-to'){if(target.id==='period-from')periodFrom=target.value;else periodTo=target.value;updateResults();return;}if(target.closest('#simulation-form,#adhesion-form'))syncBuilder(target);});
document.addEventListener('submit',async event=>{const form=event.target;if(form.id.startsWith('cash-')){event.preventDefault();await cash.submit(form);return;}if(form.id.startsWith('society-')){event.preventDefault();await society.submit(form);return;}if(!['client-form','adhesion-form','simulation-form','payment-form','settings-form','reason-form','reschedule-form'].includes(form.id))return;event.preventDefault();if(form.id==='simulation-form')return;if(saveBusy)return;saveBusy=true;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;const errorNode=form.querySelector('[role=alert]')||document.getElementById('builder-error');if(errorNode)errorNode.textContent='';let saved=false;try{
 if(form.id==='client-form'||form.id==='adhesion-form'&&builder?.mode==='new')await cep.complete(form);
 if(form.id==='client-form'){const client=readClient(form);client.archived=new FormData(form).get('archived')==='true';await rpc('jk_save_client',{p_data:client,p_id:form.dataset.id||null});saved=true;await load();navigate('clients');toast('Cliente salvo no banco.');}
 if(form.id==='adhesion-form'){const loan=builderLoan(),client=builder.mode==='new'?readClient(form):null;if(builder.mode==='existing'&&!builder.client_id)throw new Error('Selecione o cliente.');const id=await rpc('jk_create_adhesion',{p_client:client,p_client_id:builder.mode==='existing'?builder.client_id:null,p_loan:loan,p_request_id:builder.request_id});saved=true;await load();builder=null;navigate('loans');setTimeout(()=>adhesionMessage(id),0);}
 if(form.id==='payment-form'){const f=new FormData(form);const loanId=model.items.find(i=>i.id===form.dataset.id)?.loan_id;await rpc('jk_record_payment',{p_installment_id:form.dataset.id,p_amount_cents:decimalInt(f.get('amount')),p_paid_on:f.get('paid_on'),p_method:f.get('method'),p_notes:f.get('notes'),p_request_id:form.dataset.request});saved=true;await load();render();loanDetail(loanId);toast('Recebimento registrado.');}
 if(form.id==='reason-form'){const reason=new FormData(form).get('reason');if(form.dataset.kind==='reverse-payment')await rpc('jk_reverse_payment',{p_id:form.dataset.id,p_reason:reason});else await rpc('jk_change_loan',{p_id:form.dataset.id,p_action:'cancel',p_dates:null,p_reason:reason});saved=true;await load();render();toast(form.dataset.kind==='reverse-payment'?'Estorno registrado.':'Contrato cancelado.');}
 if(form.id==='reschedule-form'){const f=new FormData(form),l=model.loans.find(l=>l.id===form.dataset.id);await rpc('jk_change_loan',{p_id:l.id,p_action:'reschedule',p_dates:l.installments.map(i=>f.get('due_'+i.number)),p_reason:f.get('reason')});saved=true;await load();render();loanDetail(l.id);toast('Vencimentos atualizados.');}
 if(form.id==='settings-form'){const f=new FormData(form);await rpc('jk_save_preferences',{p_data:{default_rate_bps:decimalInt(f.get('default_rate')),default_fee_cents:decimalInt(f.get('default_fee')),due_window:Number(f.get('due_window')),message_template:f.get('message_template')}});saved=true;await load();render();toast('Preferências salvas.');}
 }catch(error){const message=saved?'A operação foi salva, mas a atualização da tela falhou. Atualize os dados antes de tentar novamente.':friendly(error);if(errorNode?.isConnected)errorNode.textContent=message;else toast(message,true);}finally{saveBusy=false;if(submit?.isConnected)submit.disabled=false;}});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
window.addEventListener('hashchange',render);
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
window.addEventListener('focus',()=>{if(session&&!saveBusy){if(route==='calendar')syncCalendar();else load().catch(()=>{});}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){syncCalendar();syncSociety();syncCash();}});
document.addEventListener('keydown',event=>{const day=event.target.closest('[data-action=calendar-day][data-date]');const offsets={ArrowLeft:-1,ArrowRight:1,ArrowUp:-7,ArrowDown:7};if(day&&event.key in offsets){event.preventDefault();selectCalendarDate(dateAdd(day.dataset.date,offsets[event.key]));}});
setInterval(()=>{syncCalendar();syncSociety();syncCash();},30000);
async function start(){try{session={private:true};await Promise.all([load(),loadProposalLogo()]);render();}catch(error){el.innerHTML=`<main class="full-error"><div class="eyebrow">JK CRED • ACESSO PRIVADO</div><h1 style="margin-top:18px">Não foi possível abrir o painel.</h1><p>${h(friendly(error))}</p><button class="btn primary" data-action="retry">${icon('refresh')}Tentar novamente</button></main>`;document.querySelector('[data-action=retry]').onclick=start;}}
start();
